export const ICON_COLORS: IconColor[] = [
	'gray', 'slate', 'brown', 'orange', 'amber', 'yellow', 'olive', 'lime', 'green', 'mint', 'teal', 'cyan', 'sky', 'blue', 'navy', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose', 'red', 'coral',
];

export function defaultIconForPath(filePath: string): string {
	if (filePath.endsWith('.base')) return 'base';

	// Images
	const imageExts = /\.(jpg|jpeg|png|gif|webp|svg|bmp|ico|tiff|tif)$/i;
	if (imageExts.test(filePath)) return 'media';

	// Videos
	const videoExts = /\.(mp4|webm|mov|avi|mkv|flv|wmv|m4v|mpg|mpeg|3gp|ogv)$/i;
	if (videoExts.test(filePath)) return 'media';

	// Audio
	const audioExts = /\.(mp3|wav|m4a|flac|aac|ogg|wma|aiff|alac|opus)$/i;
	if (audioExts.test(filePath)) return 'media';

	return 'file';
}

